ps://www.aspirexevents.com/e/rtt-afan-forest-trail-10k-and-5k-13869","status":"Open","distance":"5K","entryUrl":"https://www.tesportstiming.com/e/rtt-afan-forest-trail-10k-and-5k-15903","eventName":"RTT Afan Forest Trail 10k & 5K","eventSlug":"rtt-afan-forest-trail-10k-5k","distanceKm":5,"entryOptions":[{"status":"open","entryUrl":"https://www.tesportstiming.com/e/rtt-afan-forest-trail-10k-and-5k-15903","checkedAt":"2026-08-24T09:45:45+00:00","entryType":"third_party","isPrimary":false,"sourceUrl":"https://www.tesportstiming.com/calendars/sport-events/","isVerified":false,"providerCode":"te-sports-timing","providerName":"TE Sports Timing","priceCurrency":"GBP"}],"startTime":"11:00","notes":"Original queued source retained: https://www.tesportstiming.com/calendars/sport-events/\nStart checked 25 October 2026 against https://www.aspirexevents.com/e/rtt-afan-forest-trail-10k-and-5k-13869. The 29 November 2026 organiser programme confirms both 5K and 10K start at 11:00 Europe/London (GMT), following the separate 10:50 briefing, at Bryn Bettws Lodge, Pontrhydyfen, Port Talbot SA12 9SP."}}]}],"payload":{"events":[],"editions":[{"eventSlug":"rtt-afan-forest-trail-10k-5k","date":"2026-11-29","distance":"10K","distanceKm":10,"status":"Open","startTime":"11:00","source":"https://www.aspirexevents.com/e/rtt-afan-forest-trail-10k-and-5k-13869","notes":"Start checked 25 October 2026 against https://www.aspirexevents.com/e/rtt-afan-forest-trail-10k-and-5k-13869. The 29 November 2026 organiser programme confirms both 5K and 10K start at 11:00 Europe/London (GMT), following the separate 10:50 briefing, at Bryn Bettws Lodge, Pontrhydyfen, Port Talbot SA12 9SP."},{"eventSlug":"rtt-afan-forest-trail-10k-5k","date":"2026-11-29","distance":"5K","distanceKm":5,"status":"TBC","startTime":"11:00","source":"https://www.aspirexevents.com/e/rtt-afan-forest-trail-10k-and-5k-13869","notes":"Date and distance checked on 10 September 2026 against RunABC.\nStart checked 25 October 2026 against https://www.aspirexevents.com/e/rtt-afan-forest-trail-10k-and-5k-13869. The 29 November 2026 organiser programme confirms both 5K and 10K start at 11:00 Europe/London (GMT), following the separate 10:50 briefing, at Bryn Bettws Lodge, Pontrhydyfen, Port Talbot SA12 9SP."}]},"payload_hash":"98c3f418bf4cd3d1f7dda7d0af8de0e8e599aaaad71b4b48f6fae16a130a70a9"}'::jsonb;
  batch_id_value text := 'afan-start-reconciliation-20261025-r384';
  actor text := 'paul-authorised-afan-start-review@athrecs.com';
  previous_revision bigint; revision bigint; plan jsonb; item jsonb; candidate jsonb;
  old_payload jsonb; new_payload jsonb; before_value jsonb; after_value jsonb;
  original_384 jsonb; summary_value jsonb; live_edition editions%ROWTYPE; rows_changed int;
BEGIN
  PERFORM set_config('TimeZone','UTC',true);
  PERFORM pg_advisory_xact_lock(1095527506);
  SELECT current_revision_id INTO STRICT previous_revision FROM catalogue_publish_state WHERE id=1 FOR UPDATE;
  IF EXISTS(SELECT 1 FROM catalogue_import_batches WHERE id=batch_id_value AND status IN ('published','rolled_back')) THEN RETURN; END IF;
  IF previous_revision IS DISTINCT FROM (review->>'expected_revision')::bigint THEN RAISE EXCEPTION 'Catalogue revision changed; re-review required'; END IF;
  -- Freeze new staging and queue edits while the exact known overlaps are reconciled.
  LOCK TABLE catalogue_import_batches, catalogue_staged_rows IN SHARE ROW EXCLUSIVE MODE;
  PERFORM id FROM events WHERE id=3061155 FOR UPDATE;
  PERFORM id FROM editions WHERE event_id=3061155 FOR UPDATE;
  PERFORM id FROM edition_entry_options WHERE edition_id IN (71613968,108804223) FOR UPDATE;
  IF (SELECT to_jsonb(e) FROM events e WHERE id=3061155) IS DISTINCT FROM review->'before_event'
    OR (SELECT jsonb_agg(to_jsonb(d) ORDER BY id) FROM editions d WHERE event_id=3061155) IS DISTINCT FROM review->'before_editions'
    OR (SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY id),'[]'::jsonb) FROM edition_entry_options o WHERE edition_id IN (71613968,108804223)) IS DISTINCT FROM review->'before_options'
    OR (SELECT jsonb_agg(to_jsonb(ed) ORDER BY distance_code) FROM event_distances ed WHERE event_id=3061155) IS DISTINCT FROM review->'before_distances'
  THEN RAISE EXCEPTION 'Reviewed Afan baseline changed'; END IF;
  IF EXISTS(SELECT 1 FROM slug_redirects WHERE entity_type='event' AND old_slug='rtt-afan-forest-trail-10k-5k') THEN RAISE EXCEPTION 'Canonical slug became an alias'; END IF;
  IF (SELECT jsonb_agg(DISTINCT b.id ORDER BY b.id) FROM catalogue_import_batches b JOIN catalogue_staged_rows r ON r.batch_id=b.id WHERE b.status NOT IN ('published','rolled_back') AND (r.natural_key='rtt-afan-forest-trail-10k-5k' OR r.natural_key LIKE 'rtt-afan-forest-trail-10k-5k|%')) IS DISTINCT FROM (SELECT jsonb_agg(p->>'id' ORDER BY p->>'id') FROM jsonb_array_elements(review->'queue') p)
  THEN RAISE EXCEPTION 'Pending Afan import set changed'; END IF;
  SELECT jsonb_build_object('revision',to_jsonb(r),'changes',(SELECT jsonb_agg(to_jsonb(c) ORDER BY id) FROM catalogue_change_log c WHERE revision_id=384)) INTO original_384 FROM catalogue_revisions r WHERE id=384;
  IF jsonb_array_length(original_384->'changes')<>19 THEN RAISE EXCEPTION 'Revision 384 audit differs'; END IF;

  INSERT INTO catalogue_import_batches(id,source_key,source_url,payload_hash,payload,submitted_by)
    VALUES(batch_id_value,review->>'source_key',review->>'source',review->>'payload_hash',review->'payload',actor);
  INSERT INTO catalogue_staged_rows(batch_id,row_type,row_number,natural_key,payload)
    SELECT batch_id_value,'edition',ordinality::int,concat_ws('|',value->>'eventSlug',value->>'date',value->>'distance'),value FROM jsonb_array_elements(review->'payload'->'editions') WITH ORDINALITY;
  UPDATE catalogue_import_batches SET status='validating' WHERE id=batch_id_value;
  IF (SELECT count(*) FROM catalogue_staged_rows WHERE batch_id=batch_id_value)<>2 OR EXISTS (
    SELECT 1 FROM catalogue_staged_rows r WHERE batch_id=batch_id_value AND
      (r.payload->>'eventSlug'<>'rtt-afan-forest-trail-10k-5k' OR r.payload->>'date'<>'2026-11-29' OR r.payload->>'distance' NOT IN ('5K','10K') OR r.payload->>'startTime'<>'11:00' OR r.payload->>'source'<>review->>'source' OR r.payload->>'status' NOT IN ('Open','TBC') OR NOT EXISTS(SELECT 1 FROM editions d WHERE d.event_id=3061155 AND d.event_date=(r.payload->>'date')::date AND d.distance_code=r.payload->>'distance' AND d.distance_km=(r.payload->>'distanceKm')::float)))
  THEN RAISE EXCEPTION 'Afan staged validation failed'; END IF;
  UPDATE catalogue_import_batches SET status='ready',validated_at=now(),validation_summary=jsonb_build_object('events',0,'editions',2,'invalidRows',0,'errors','[]'::jsonb,'checks',jsonb_build_array('official edition programme','canonical IDs','complete baseline','pending set and full payload hashes','exact scope','no additions'),'queueReconciliation',review->'queue','timeZone','Europe/London','source',review->>'source','checkedAt','2026-10-25') WHERE id=batch_id_value;

  FOR plan IN SELECT value FROM jsonb_array_elements(review->'queue') LOOP
    SELECT payload INTO STRICT old_payload FROM catalogue_import_batches WHERE id=plan->>'id' AND source_key=plan->>'source_key' AND status='ready' AND payload_hash=plan->>'before_hash' AND md5(payload::text)=plan->>'before_md5' AND validation_summary=plan->'before_validation_summary' AND validated_at=(plan->>'before_validated_at')::timestamptz AND error IS NOT DISTINCT FROM plan->>'before_error' FOR UPDATE;
    new_payload:=old_payload;
    FOR item IN SELECT value FROM jsonb_array_elements(plan->'rows') LOOP
      IF old_payload->'editions'->((item->>'row_number')::int-1) IS DISTINCT FROM item->'before' THEN RAISE EXCEPTION 'Queued source payload changed'; END IF;
      UPDATE catalogue_staged_rows SET payload=item->'after' WHERE batch_id=plan->>'id' AND row_type='edition' AND row_number=(item->>'row_number')::int AND payload=item->'before' AND validation_errors='[]'::jsonb AND natural_key=concat_ws('|',item->'before'->>'eventSlug',item->'before'->>'date',item->'before'->>'distance');
      GET DIAGNOSTICS rows_changed=ROW_COUNT;
      IF rows_changed<>1 THEN RAISE EXCEPTION 'Queued staged row changed'; END IF;
      new_payload:=jsonb_set(new_payload,ARRAY['editions',((item->>'row_number')::int-1)::text],item->'after');
    END LOOP;
    UPDATE catalogue_import_batches SET payload=new_payload,payload_hash=plan->>'after_hash',validated_at=now(),validation_summary=validation_summary||jsonb_build_object('afanStartReconciliation',jsonb_build_object('auditBatch',batch_id_value,'checkedAt','2026-10-25','source',review->>'source','amendedRows',2)) WHERE id=plan->>'id';
  END LOOP;

  UPDATE catalogue_import_batches SET status='publishing' WHERE id=batch_id_value AND status='ready';
  INSERT INTO catalogue_revisions(batch_id,previous_revision_id,published_by) VALUES(batch_id_value,previous_revision,actor) RETURNING id INTO revision;
  FOR candidate IN SELECT value FROM jsonb_array_elements(review->'payload'->'editions') LOOP
    SELECT * INTO STRICT live_edition FROM editions WHERE event_id=3061155 AND event_date='2026-11-29' AND distance_code=candidate->>'distance';
    SELECT jsonb_build_object('record',to_jsonb(live_edition),'entryOptions',coalesce((SELECT jsonb_agg(to_jsonb(o) ORDER BY is_primary,provider_code) FROM edition_entry_options o WHERE edition_id=live_edition.id),'[]'::jsonb)) INTO before_value;
    UPDATE editions SET start_time=candidate->>'startTime',source_url=candidate->>'source',notes=candidate->>'notes' WHERE id=live_edition.id;
    SELECT jsonb_build_object('record',to_jsonb(ed),'entryOptions',coalesce((SELECT jsonb_agg(to_jsonb(o) ORDER BY is_primary,provider_code) FROM edition_entry_options o WHERE edition_id=ed.id),'[]'::jsonb)) INTO after_value FROM editions ed WHERE id=live_edition.id;
    IF ((after_value->'record')-ARRAY['start_time','source_url','notes']) IS DISTINCT FROM ((before_value->'record')-ARRAY['start_time','source_url','notes']) OR after_value->'entryOptions' IS DISTINCT FROM before_value->'entryOptions' THEN RAISE EXCEPTION 'Unexpected edition mutation'; END IF;
    INSERT INTO catalogue_change_log(revision_id,entity_type,entity_key,operation,before_json,after_json) VALUES(revision,'edition',concat_ws('|',candidate->>'eventSlug',candidate->>'date',candidate->>'distance'),'update',before_value,after_value);
  END LOOP;
  IF (SELECT to_jsonb(e) FROM events e WHERE id=3061155) IS DISTINCT FROM review->'before_event' THEN RAISE EXCEPTION 'Event identity changed'; END IF;
  IF original_384 IS DISTINCT FROM (SELECT jsonb_build_object('revision',to_jsonb(r),'changes',(SELECT jsonb_agg(to_jsonb(c) ORDER BY id) FROM catalogue_change_log c WHERE revision_id=384)) FROM catalogue_revisions r WHERE id=384) THEN RAISE EXCEPTION 'Revision 384 was modified'; END IF;
  summary_value:=jsonb_build_object('revisionId',revision,'newEvents',0,'newEditions',0,'newStarts',1,'reconfirmedStarts',1,'editionsUpserted',2,'entryOptionsUpserted',0,'reconciledPendingBatches',6,'reconciledPendingRows',12,'rollbackNote','Edition snapshots support normal rollback. Queue amendments intentionally retain organiser-confirmed starts; original queue rows and hashes are in validation_summary.queueReconciliation.');
  UPDATE catalogue_revisions SET summary=summary_value WHERE id=revision;
  UPDATE catalogue_import_batches SET status='published',published_at=now(),publish_summary=summary_value WHERE id=batch_id_value;
  UPDATE catalogue_publish_state SET current_revision_id=revision,updated_at=now() WHERE id=1;
END $afan$;
